import {test} from 'node:test';import assert from 'node:assert/strict';import {DatabaseSync} from 'node:sqlite';import {applyDomains,DOMAINS,ACCOUNT,ENDPOINT,SELECT,UPSERT} from './apply.mjs';
const env={GITHUB_ACTIONS:'true',GITHUB_REPOSITORY:'gradient30/laboratory',GITHUB_REF:'refs/heads/registration-domains-20261026',GITHUB_EVENT_NAME:'push',LAB_DOMAIN_APPROVAL:'owner-approved-four-domains-20261026',CLOUDFLARE_ACCOUNT_ID:ACCOUNT,CLOUDFLARE_API_TOKEN:'synthetic-token'};
function setup(value){const db=new DatabaseSync(':memory:');db.exec('CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at INTEGER NOT NULL)');if(value!==undefined)db.prepare('INSERT INTO settings VALUES(?,?,?)').run('allowedDomains',JSON.stringify(value),1);db.prepare('INSERT INTO settings VALUES(?,?,?)').run('progressionMode','sequential',1);let calls=0;const fetchImpl=async(url,o)=>{calls++;assert.equal(url,ENDPOINT);assert.equal(o.redirect,'error');assert.equal(o.method,'POST');const b=JSON.parse(o.body);assert.ok([SELECT,UPSERT].includes(b.sql));return {ok:true,json:async()=>({success:true,result:[{success:true,results:db.prepare(b.sql).all(...b.params)}]})}};return {db,fetchImpl,calls:()=>calls}}
for(const before of [undefined,[]])test('exact four-domain write from empty/missing policy '+JSON.stringify(before),async()=>{const h=setup(before);const r=await applyDomains({env,fetchImpl:h.fetchImpl,now:()=>1793014000123});assert.equal(r.status,'configured');assert.deepEqual(r.allowedDomains,DOMAINS);assert.equal(h.calls(),3);assert.equal(h.db.prepare("SELECT updated_at FROM settings WHERE key='allowedDomains'").get().updated_at,1793014000);assert.equal(h.db.prepare("SELECT value FROM settings WHERE key='progressionMode'").get().value,'sequential')});
test('idempotent metadata read only',async()=>{const h=setup(DOMAINS);assert.equal((await applyDomains({env,fetchImpl:h.fetchImpl})).status,'already-configured');assert.equal(h.calls(),1)});
test('other nonempty policy not overwritten',async()=>{const h=setup(['other.test']);await assert.rejects(applyDomains({env,fetchImpl:h.fetchImpl}));assert.equal(h.calls(),1)});
for(const key of Object.keys(env))test('guard before network '+key,async()=>{let calls=0;await assert.rejects(applyDomains({env:{...env,[key]:''},fetchImpl:async()=>{calls++}}));assert.equal(calls,0)});
test('concurrent policy change protected by CAS',async()=>{const h=setup([]);let calls=0;await assert.rejects(applyDomains({env,fetchImpl:async(...args)=>{if(++calls===2)h.db.prepare("UPDATE settings SET value='[\"other.test\"]',updated_at=2 WHERE key='allowedDomains'").run();return h.fetchImpl(...args)}}));assert.equal(JSON.parse(h.db.prepare("SELECT value FROM settings WHERE key='allowedDomains'").get().value)[0],'other.test')});
test('missing-row race never overwrites',async()=>{const h=setup();let calls=0;await assert.rejects(applyDomains({env,fetchImpl:async(...args)=>{if(++calls===2)h.db.prepare("INSERT INTO settings VALUES('allowedDomains','[\"other.test\"]',2)").run();return h.fetchImpl(...args)}}))});
test('ambiguous response no automatic retry or error exposure',async()=>{let calls=0;await assert.rejects(applyDomains({env,fetchImpl:async()=>{calls++;throw Error('private-provider-body')}}),e=>!e.message.includes('private'));assert.equal(calls,1)});

test('present-row deletion race cannot recreate policy',async()=>{const h=setup([]);let calls=0;await assert.rejects(applyDomains({env,fetchImpl:async(...args)=>{if(++calls===2)h.db.prepare("DELETE FROM settings WHERE key='allowedDomains'").run();return h.fetchImpl(...args)}}));assert.equal(h.db.prepare("SELECT value FROM settings WHERE key='allowedDomains'").get(),undefined)});
test('ambiguous write does not retry',async()=>{const h=setup([]);let calls=0;await assert.rejects(applyDomains({env,fetchImpl:async(...args)=>{calls++;const result=await h.fetchImpl(...args);if(calls===2){await result.json();throw Error('private-mutation-response');}return result}}),e=>!e.message.includes('private'));assert.equal(calls,2);assert.deepEqual(JSON.parse(h.db.prepare("SELECT value FROM settings WHERE key='allowedDomains'").get().value),DOMAINS)});
